```cell
const fork = await ctx.call("tevm/fork", { rpcUrl: "https://ethereum-rpc.publicnode.com", blockTag: "latest" })
const vitalik = "0xd8dA6BF26964aF9D7eEd9e03E53415D37aA96045"
const bal = await ctx.call("tevm/getBalance", { address: vitalik, blockTag: "latest" })
const pane = await ctx.call("ui/pane", { name: "balances", props: { rows: [{ label: "vitalik.eth", address: vitalik, wei: bal.wei, ether: bal.ether }] }, title: "vitalik.eth ETH balance on mainnet" })
console.log({ fork, bal, pane })
```
